import React, { useState, useEffect } from 'react';
import './index.css';
import { Task, DayData, TomorrowPlan } from './types';
import NightReview from './components/NightReview';
import Reports from './components/Reports';
import Sidebar from './components/Sidebar';

const App: React.FC = () => {
  const [currentDay, setCurrentDay] = useState(1);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [points, setPoints] = useState(0);
  const [streak, setStreak] = useState(0);
  const [badges, setBadges] = useState<string[]>([]);
  const [currentView, setCurrentView] = useState('dashboard');
  const [showNightReview, setShowNightReview] = useState(false);
  const [tomorrowPlan, setTomorrowPlan] = useState<TomorrowPlan>({
    englishTopic: '',
    tradingStrategy: '',
    dsaTopic: '',
    flutterReactChapter: ''
  });
  const [darkMode, setDarkMode] = useState(true);
  const [history, setHistory] = useState<DayData[]>([]);

  useEffect(() => {
    // Initialize data from localStorage
    const savedData = localStorage.getItem('trackerData');
    if (savedData) {
      const parsed = JSON.parse(savedData);
      setCurrentDay(parsed.currentDay || 1);
      setTasks(parsed.tasks || []);
      setPoints(parsed.points || 0);
      setStreak(parsed.streak || 0);
      setBadges(parsed.badges || []);
    } else {
      // Initialize with default tasks
      initializeTasks();
    }
  }, []);

  useEffect(() => {
    // Save to localStorage whenever state changes
    const data = {
      currentDay,
      tasks,
      points,
      streak,
      badges
    };
    localStorage.setItem('trackerData', JSON.stringify(data));
  }, [currentDay, tasks, points, streak, badges]);

  const initializeTasks = () => {
    const isWeekday = new Date().getDay() >= 1 && new Date().getDay() <= 5;
    const defaultTasks: Task[] = [
      // Morning Routine (Every Day)
      { id: '1', category: 'Morning Routine', title: 'Wake up and freshen up', time: '6:00–6:30 AM', completed: false, skipped: false },
      { id: '2', category: 'Morning Routine', title: '10 min meditation + 10 min manifestation & gratitude', time: '6:30–6:50 AM', completed: false, skipped: false },
      { id: '3', category: 'English Learning', title: '5 new words with sentences', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '4', category: 'English Learning', title: '10 min book reading in English', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '5', category: 'English Learning', title: '1 YouTube lecture (finish completely)', time: '7:00–8:15 AM', completed: false, skipped: false },

      // Trading
      { id: '6', category: 'Trading', title: 'Trade planning + minimum 2–3 live trades', time: '9:00–9:40 AM', completed: false, skipped: false },
      { id: '7', category: 'Trading', title: isWeekday ? 'Trade analysis and learning (after office)' : '2 full hours of trading practice', time: isWeekday ? '7:00–7:30 PM' : 'Full session', completed: false, skipped: false },

      // Coding/DSA
      { id: '8', category: 'Coding/DSA', title: isWeekday ? 'DSA + Flutter questions (30 min)' : 'DSA practice (1 hour)', time: isWeekday ? '9:00–9:30 PM' : 'Flexible', completed: false, skipped: false },

      // Flutter/React Development
      { id: '9', category: 'Flutter/React', title: getDevelopmentTask(currentDay), time: getDevelopmentTime(currentDay, isWeekday), completed: false, skipped: false },

      // Night Review
      { id: '10', category: 'Night Review', title: 'Check all completed/missed tasks', time: 'Before sleep', completed: false, skipped: false },
      { id: '11', category: 'Night Review', title: 'Plan next day\'s topics', time: 'Before sleep', completed: false, skipped: false },
      { id: '12', category: 'Night Review', title: 'Write short note before sleeping', time: 'Before sleep', completed: false, skipped: false },
    ];
    setTasks(defaultTasks);
  };

  const getDevelopmentTask = (day: number) => {
    if (day <= 30) return 'Flutter development session';
    return 'Flutter + React development session';
  };

  const getDevelopmentTime = (day: number, isWeekday: boolean) => {
    if (day <= 30) {
      return isWeekday ? '9:30 PM–1:00 AM (3 hrs)' : '10 hrs Flutter';
    }
    return isWeekday ? '1.5 hrs Flutter + 2 hrs React' : '5 hrs Flutter + 5 hrs React';
  };

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(task => {
      if (task.id === id) {
        return { ...task, completed: !task.completed, skipped: false };
      }
      return task;
    }));
  };

  const skipTask = (id: string) => {
    setTasks(prev => prev.map(task => {
      if (task.id === id) {
        return { ...task, skipped: !task.skipped, completed: false };
      }
      return task;
    }));
  };

  const completeNightReview = () => {
    const todayData: DayData = {
      day: currentDay,
      date: new Date().toISOString(),
      tasks: tasks,
      points: calculatePoints(),
      streak: tasks.every(task => task.completed) ? streak + 1 : 0,
      completed: tasks.every(task => task.completed),
      grade: calculateGrade()
    };

    setHistory([...history, todayData]);
    setPoints(points + todayData.points);
    setStreak(todayData.streak);

    // Check for badges
    const newBadges = [...badges];
    if (todayData.streak === 7 && !badges.includes('Week Warrior')) {
      newBadges.push('Week Warrior');
      setPoints(points + 50);
    }
    if (todayData.streak === 30 && !badges.includes('Month Master')) {
      newBadges.push('Month Master');
      setPoints(points + 200);
    }
    if (currentDay === 180 && !badges.includes('Champion')) {
      newBadges.push('Champion');
    }
    setBadges(newBadges);

    // Move to next day
    setCurrentDay(currentDay + 1);
    initializeTasks();
    setShowNightReview(false);
  };

  const calculatePoints = () => {
    let totalPoints = 0;
    const isWeekday = new Date().getDay() >= 1 && new Date().getDay() <= 5;

    tasks.forEach(task => {
      if (task.completed) {
        // Reward points
        if (task.category === 'Trading') totalPoints += 10;
        else if (task.category === 'Flutter/React') totalPoints += 10;
        else if (task.category === 'Coding/DSA') totalPoints += 8;
        else if (task.category === 'Morning Routine') totalPoints += 5;
        else if (task.category === 'Night Review') totalPoints += 5;
        else totalPoints += 3; // English Learning
      } else if (task.skipped) {
        // Penalty points
        if (task.category === 'Trading') totalPoints -= 10;
        else if (task.category === 'Flutter/React') totalPoints -= 10;
        else if (task.category === 'Coding/DSA') totalPoints -= 8;
        else if (task.category === 'Morning Routine') totalPoints -= 5;
        else if (task.category === 'Night Review') totalPoints -= 5;
        else totalPoints -= 3; // English Learning
      }
    });

    // Bonus for completing all tasks
    const allCompleted = tasks.every(task => task.completed);
    if (allCompleted) {
      totalPoints += 20;
    }

    // Penalty for missing all tasks
    const allMissed = tasks.every(task => !task.completed);
    if (allMissed) {
      totalPoints -= 30;
    }

    return totalPoints;
  };

  const calculateGrade = () => {
    const completedTasks = tasks.filter(t => t.completed).length;
    const totalTasks = tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage >= 90) return 'A';
    if (percentage >= 80) return 'B';
    if (percentage >= 70) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
  };
  const completedTasks = tasks.filter(t => t.completed).length;
  const totalTasks = tasks.length;
  const completionPercentage = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  const getPhase = () => {
    if (currentDay <= 30) return { name: 'Phase 1', description: 'Flutter Focus', color: 'text-blue-400' };
    if (currentDay <= 60) return { name: 'Phase 2', description: 'Flutter + React Intro', color: 'text-purple-400' };
    return { name: 'Phase 3', description: 'Full Stack + Trading Mastery', color: 'text-green-400' };
  };

  const phase = getPhase();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  return (
    <div className={`min-h-screen ${darkMode ? 'bg-dark-primary text-dark-text' : 'bg-gray-50 text-gray-900'} flex`}>
      <Sidebar 
        currentView={currentView}
        setCurrentView={setCurrentView}
        darkMode={darkMode}
        setDarkMode={setDarkMode}
      />

      <div className="flex-1">
        {/* Header */}
        <div className={`${darkMode ? 'bg-dark-secondary border-b border-dark-accent' : 'bg-white border-b border-gray-200'}`}>
          <div className="max-w-7xl mx-auto px-4 py-6">
            <div className="flex justify-between items-center">
              <div>
                <h1 className="text-3xl font-bold text-white">180-Day Challenge Tracker</h1>
                <p className={darkMode ? 'text-dark-text-secondary mt-1' : 'text-gray-600 mt-1'}>{today}</p>
              </div>
              <div className="text-right">
                <div className="text-2xl font-bold text-white">Day {currentDay} of 180</div>
                <div className={`text-sm ${phase.color}`}>{phase.name}: {phase.description}</div>
              </div>
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        <div className={darkMode ? 'bg-dark-accent' : 'bg-gray-100'}>
          <div className="max-w-7xl mx-auto px-4 py-3">
            <div className="flex items-center justify-between mb-2">
              <span className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Overall Progress</span>
              <span className="text-sm font-bold text-white">{completionPercentage}%</span>
            </div>
            <div className={`w-full ${darkMode ? 'bg-dark-secondary' : 'bg-gray-300'} rounded-full h-3`}>
              <div 
                className="bg-gradient-to-r from-blue-500 to-purple-500 h-3 rounded-full transition-all duration-500"
                style={{ width: `${(currentDay / 180) * 100}%` }}
              />
            </div>
          </div>
        </div>

        {/* Main Content */}
        {currentView === 'dashboard' && (
          <div className="max-w-7xl mx-auto px-4 py-8">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Dashboard */}
              <div className="lg:col-span-2">
                <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6 mb-6`}>
                  <div className="flex justify-between items-center mb-6">
                    <h2 className="text-xl font-bold text-white">Today's Tasks</h2>
                    <button
                      onClick={() => setCurrentView('reports')}
                      className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
                    >
                      View Report
                    </button>
                  </div>

                  {/* Tasks by Category */}
                  {['Morning Routine', 'English Learning', 'Trading', 'Coding/DSA', 'Flutter/React', 'Night Review'].map(category => {
                    const categoryTasks = tasks.filter(t => t.category === category);
                    if (categoryTasks.length === 0) return null;

                    return (
                      <div key={category} className="mb-6">
                        <h3 className="text-lg font-semibold text-white mb-3 flex items-center">
                          <span className="w-2 h-2 bg-blue-400 rounded-full mr-2"></span>
                          {category}
                        </h3>
                        <div className="space-y-2">
                          {categoryTasks.map(task => (
                            <div key={task.id} className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} rounded-lg p-4 flex items-center justify-between`}>
                              <div className="flex items-center space-x-3">
                                <input
                                  type="checkbox"
                                  checked={task.completed}
                                  onChange={() => toggleTask(task.id)}
                                  className="w-5 h-5 text-blue-500 bg-dark-accent border-dark-muted rounded focus:ring-blue-500 focus:ring-2"
                                />
                                <div>
                                  <div className={`font-medium ${task.completed ? 'text-green-400 line-through' : 'text-white'}`}>
                                    {task.title}
                                  </div>
                                  {task.time && (
                                    <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>{task.time}</div>
                                  )}
                                </div>
                              </div>
                              <div className="flex items-center space-x-2">
                                {task.completed && (
                                  <span className="text-green-400 text-sm font-medium">Completed</span>
                                )}
                                {task.skipped && (
                                  <span className="text-yellow-400 text-sm font-medium">Skipped</span>
                                )}
                                {!task.completed && !task.skipped && (
                                  <span className={darkMode ? 'text-dark-text-secondary text-sm font-medium' : 'text-gray-500 text-sm font-medium'}>Pending</span>
                                )}
                                <button
                                  onClick={() => skipTask(task.id)}
                                  className={`px-3 py-1 text-xs ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-md transition-colors`}
                                >
                                  Skip
                                </button>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}
                </div>

                {/* Daily Schedule Timeline */}
                <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6`}>
                  <h3 className="text-lg font-bold text-white mb-4">Daily Schedule Timeline</h3>
                  <div className="space-y-3">
                    {[
                      { time: '6:00–6:30 AM', task: 'Wake up and freshen up', category: 'Morning' },
                      { time: '6:30–6:50 AM', task: 'Meditation + Manifestation', category: 'Morning' },
                      { time: '7:00–8:15 AM', task: 'English Practice', category: 'English' },
                      { time: '9:00–9:40 AM', task: 'Trading Session', category: 'Trading' },
                      { time: '7:00–7:30 PM', task: 'Trade Analysis', category: 'Trading' },
                      { time: '9:00–9:30 PM', task: 'DSA Practice', category: 'Coding' },
                      { time: '9:30 PM–1:00 AM', task: 'Development Session', category: 'Dev' },
                      { time: 'Before Sleep', task: 'Night Review', category: 'Review' }
                    ].map((schedule, index) => (
                      <div key={index} className={`flex items-center space-x-4 p-3 rounded-lg ${darkMode ? 'bg-dark-primary' : 'bg-gray-50'}`}>
                        <div className="text-sm font-medium text-blue-400 w-32">{schedule.time}</div>
                        <div className="flex-1">
                          <div className="text-white font-medium">{schedule.task}</div>
                          <div className={`text-xs ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>{schedule.category}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Stats Sidebar */}
              <div className="space-y-6">
                {/* Progress Ring */}
                <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6`}>
                  <h3 className="text-lg font-bold text-white mb-4">Daily Progress</h3>
                  <div className="flex justify-center mb-4">
                    <div className="relative w-32 h-32">
                      <svg className="progress-ring w-32 h-32">
                        <circle
                          className={darkMode ? 'text-dark-accent' : 'text-gray-300'}
                          stroke="currentColor"
                          strokeWidth="8"
                          fill="transparent"
                          r="56"
                          cx="64"
                          cy="64"
                        />
                        <circle
                          className="progress-ring-circle text-blue-500"
                          stroke="currentColor"
                          strokeWidth="8"
                          strokeDasharray={`${2 * Math.PI * 56}`}
                          strokeDashoffset={`${2 * Math.PI * 56 * (1 - completionPercentage / 100)}`}
                          fill="transparent"
                          r="56"
                          cx="64"
                          cy="64"
                        />
                      </svg>
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-2xl font-bold text-white">{completionPercentage}%</span>
                      </div>
                    </div>
                  </div>
                  <div className={`text-center ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>
                    {completedTasks} of {totalTasks} tasks completed
                  </div>
                </div>

                {/* Points & Streak */}
                <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6`}>
                  <h3 className="text-lg font-bold text-white mb-4">Achievements</h3>
                  <div className="space-y-3">
                    <div className="flex justify-between items-center">
                      <span className={darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}>Total Points</span>
                      <span className="text-xl font-bold text-yellow-400">{points}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className={darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}>Current Streak</span>
                      <span className="text-xl font-bold text-orange-400">{streak} days</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className={darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}>Badges</span>
                      <span className="text-sm font-medium text-purple-400">{badges.length} earned</span>
                    </div>
                  </div>
                </div>

                {/* Motivational Quote */}
                <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl p-6">
                  <h3 className="text-lg font-bold text-white mb-3">Daily Motivation</h3>
                  <p className="text-white italic">
                    "Success is the sum of small efforts repeated day in and day out."
                  </p>
                  <p className="text-white text-sm mt-2">- Robert Collier</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Reports View */}
        {currentView === 'reports' && (
          <Reports 
            history={history}
            darkMode={darkMode}
            onClose={() => setCurrentView('dashboard')}
          />
        )}
      </div>

      {/* Night Review Modal */}
      {showNightReview && (
        <NightReview
          tasks={tasks}
          tomorrowPlan={tomorrowPlan}
          setTomorrowPlan={setTomorrowPlan}
          onComplete={completeNightReview}
          onClose={() => setShowNightReview(false)}
          darkMode={darkMode}
        />
      )}
    </div>
  );
};

export default App;
